import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.Base64
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import scala.jdk.CollectionConverters._
import scala.util.Try

object CryptoConfig {
  val SECRET_KEY: String = sys.env.getOrElse("AUTH_SECRET", "")
  require(SECRET_KEY.nonEmpty, "AUTH_SECRET must be set")

  // Supported algorithms for forward compatibility
  val ALLOWED_ALGORITHMS: Set[String] = Set(
    "HmacSHA256",
    "HmacSHA384", 
    "HmacSHA512"
  )

  val DEFAULT_ALGORITHM = "HmacSHA256"
  val TOKEN_VERSION = 2
  val MAX_TOKEN_AGE_MS = 300000L // 5 minutes
}

class TokenService {
  private val tokenCache = new ConcurrentHashMap[String, Long](256)

  private def constantTimeEquals(a: Array[Byte], b: Array[Byte]): Boolean = {
    if (a.length != b.length) return false
    var result: Int = 0
    var i = 0
    while (i < a.length) {
      result |= (a(i) ^ b(i))
      i += 1
    }
    result == 0
  }

  private def computeHmac(algorithm: String, data: Array[Byte]): Array[Byte] = {
    val keySpec = new SecretKeySpec(
      CryptoConfig.SECRET_KEY.getBytes("UTF-8"), algorithm
    )
    val mac = Mac.getInstance(algorithm)
    mac.init(keySpec)
    mac.doFinal(data)
  }

  private def resolveAlgorithm(requested: String): Option[String] = {
    // Normalize algorithm name for comparison
    val normalized = requested.trim.toLowerCase
    CryptoConfig.ALLOWED_ALGORITHMS.find(_.toLowerCase == normalized)
  }

  // Prune expired entries to prevent unbounded memory growth of the replay cache.
  private def pruneExpired(): Unit = {
    val cutoff = System.currentTimeMillis() - CryptoConfig.MAX_TOKEN_AGE_MS
    val it = tokenCache.entrySet().iterator()
    while (it.hasNext) {
      val entry = it.next()
      if (entry.getValue < cutoff) {
        it.remove()
      }
    }
  }

  def createToken(userId: String, algorithm: String = CryptoConfig.DEFAULT_ALGORITHM): String = {
    val resolvedAlg = resolveAlgorithm(algorithm).getOrElse(CryptoConfig.DEFAULT_ALGORITHM)
    val timestamp = System.currentTimeMillis()
    val payload = s"""v=${CryptoConfig.TOKEN_VERSION}&alg=$resolvedAlg&uid=$userId&ts=$timestamp"""
    val payloadBytes = payload.getBytes("UTF-8")
    val signature = computeHmac(resolvedAlg, payloadBytes)
    val encodedPayload = Base64.getUrlEncoder.withoutPadding.encodeToString(payloadBytes)
    val encodedSig = Base64.getUrlEncoder.withoutPadding.encodeToString(signature)
    s"$encodedPayload.$encodedSig"
  }

  def validateToken(token: String, expectedUserId: String): Boolean = {
    Try {
      val parts = token.split("\\.", -1)
      if (parts.length != 2) return false

      val payloadBytes = Base64.getUrlDecoder.decode(parts(0))
      val providedSig = Base64.getUrlDecoder.decode(parts(1))
      val payload = new String(payloadBytes, "UTF-8")

      // Parse payload fields
      val fields = payload.split("&").map { field =>
        val kv = field.split("=", 2)
        if (kv.length == 2) (kv(0), kv(1)) else (kv(0), "")
      }.toMap

      // Validate version
      val version = fields.getOrElse("v", "0").toInt
      if (version != CryptoConfig.TOKEN_VERSION) return false

      // Validate timestamp
      val timestamp = fields.getOrElse("ts", "0").toLong
      val age = System.currentTimeMillis() - timestamp
      if (age < 0 || age > CryptoConfig.MAX_TOKEN_AGE_MS) return false

      // Validate userId
      val tokenUserId = fields.getOrElse("uid", "")
      if (tokenUserId != expectedUserId) return false

      // Always use the server's default algorithm for verification
      // Never trust client-specified algorithm
      val verificationAlg = CryptoConfig.DEFAULT_ALGORITHM

      // Recompute signature using server-side algorithm
      val expectedSig = computeHmac(verificationAlg, payloadBytes)

      // Opportunistically prune expired replay-cache entries to bound memory usage.
      pruneExpired()

      // Check for token reuse
      val tokenId = s"${tokenUserId}_${timestamp}"
      val prev = tokenCache.putIfAbsent(tokenId, System.currentTimeMillis())
      if (prev != null) return false

      constantTimeEquals(expectedSig, providedSig)
    }.getOrElse(false)
  }
}

// gRPC-style interceptor
trait ServerInterceptor {
  def intercept(userId: String, token: String): Either[String, String]
}

class AuthInterceptor(tokenService: TokenService) extends ServerInterceptor {
  override def intercept(userId: String, token: String): Either[String, String] = {
    if (userId == null || userId.isEmpty) {
      return Left("UNAUTHENTICATED: missing user id")
    }
    if (token == null || token.isEmpty) {
      return Left("UNAUTHENTICATED: missing token")
    }
    if (tokenService.validateToken(token, userId)) {
      Right(userId)
    } else {
      Left("UNAUTHENTICATED: invalid token")
    }
  }
}
